"use client";

import { useState } from "react";

import ScrambleHover from "@/registry/new-york/scramble-hover";

export const ScrambleHoverPreview = () => {
  const [direction, setDirection] = useState<"start" | "end" | "center">(
    "start"
  );

  return (
    <div className="flex flex-col items-center gap-16 px-6 py-16">
      <div className="flex flex-col items-center gap-4 text-center">
        <h1 className="text-5xl font-medium tracking-tight text-foreground sm:text-6xl md:text-7xl">
          <ScrambleHover
            text="Move your cursor"
            scrambleSpeed={40}
            sequential
            revealDirection={direction}
            scrambledClassName="text-muted-foreground/50"
            className="font-mono"
          />
        </h1>
        <p className="text-sm text-muted-foreground tracking-wide uppercase">
          Hover to scramble
        </p>
      </div>

      <div className="flex flex-wrap items-center justify-center gap-2">
        {(["start", "center", "end"] as const).map((dir) => (
          <button
            key={dir}
            type="button"
            onClick={() => setDirection(dir)}
            className={`rounded-full border border-border px-4 py-1.5 text-xs font-medium tracking-wide uppercase transition-colors ${direction === dir ? "bg-foreground text-background" : "bg-transparent text-muted-foreground hover:text-foreground"}`}
          >
            {dir}
          </button>
        ))}
      </div>
    </div>
  );
};

input.content:
"use client";

import { useState } from "react";

import ScrambleIn from "@/registry/new-york/scramble-in";

export const ScrambleInPreview = () => {
  const [speed, setSpeed] = useState(40);

  return (
    <div className="flex flex-col items-center gap-16 px-6 py-16">
      <div className="flex flex-col items-center gap-4 text-center">
        <h1 className="text-5xl font-medium tracking-tight text-foreground font-mono sm:text-6xl md:text-7xl">
          <ScrambleIn
            text="Built for developers"
            scrambleSpeed={speed}
            scrambledLetterCount={3}
            className="font-mono"
            scrambledClassName="font-mono"
          />
        </h1>
        <p className="text-sm text-muted-foreground tracking-wide uppercase">
          Animated text reveal
        </p>
      </div>

      <div className="flex flex-col items-center gap-8">
        <p className="max-w-md text-center text-lg text-muted-foreground leading-relaxed font-mono">
          <ScrambleIn
            text="Every animation resolves into clarity."
            scrambleSpeed={25}
            scrambledLetterCount={2}
            className="font-mono"
            scrambledClassName="font-mono"
          />
        </p>

        <div className="flex items-center gap-4">
          <span className="text-xs text-muted-foreground uppercase tracking-wide">
            Speed
          </span>
          <input
            type="range"
            min="10"
            max="80"
            value={speed}
            onChange={(e) => setSpeed(Number(e.target.value))}
            className="w-32 accent-foreground"
          />
          <span className="text-xs text-muted-foreground font-mono">
            {speed}ms
          </span>
        </div>
      </div>
    </div>
  );
};

